def is_power_of_5(N):
    """Checks if N is a power of 5."""
    if N <= 0:
        return False
    if N == 1:
        return True
    while N > 1:
        if N % 5 != 0:
            return False
        N //= 5
    return True

solutions = []
# Iterate n such that n >= 3, n < 60, and n % 4 == 3
for n in range(3, 60, 4):
    value = 2**n - 3
    if is_power_of_5(value):
        solutions.append(n)
        print(f"Solution found: n = {n}, 2^n - 3 = {value}")

print("\nAll solutions found in the specified range:", solutions)
